import {shellBatchLabel} from './tank-shell-layout.js';
import {fmt,esc} from './tank-visuals.js';
export function stockChoiceMarkup(c,{selected=false,badges=[]}={}){
  const r=c.result;
  const main=r.valid?`<b>${r.plateSheets} 張${r.stockComplete?'原板':'已排 · 備料未完整'}</b><span class="tank-stock-price">${r.stockWeight===null?'已知 '+fmt(r.stockPlan.knownStockWeight)+' kg · 部分密度待填':(r.stockComplete?'原板':'可排部分')+' '+fmt(r.stockWeight)+' kg'}${r.stockPlan.groups.length?' · '+r.stockPlan.groups.length+' 組材料':''}</span>`:`<span class="tank-stock-warning">${esc(r.issues[0].message)}</span>`;
  const more=r.valid?`<details class="tank-stock-detail"><summary>接縫、餘料與利用率</summary><dl><div><dt>筒身分片</dt><dd>${shellBatchLabel(r)}</dd></div><div><dt>筒身接縫</dt><dd>${r.verticalSeams} 縱縫＋${r.horizontalSeams} 環縫</dd></div><div><dt>筒身焊縫</dt><dd>約 ${fmt(r.weldLength/1000,2)} m</dd></div><div><dt>餘料</dt><dd>${fmt(r.offcutWeight)} kg</dd></div><div><dt>毛坯利用</dt><dd>${fmt(r.utilization)}%</dd></div></dl></details>`:'';
  return `<article class="tank-stock-card"><button type="button" data-stock="${c.id}" data-stock-width="${c.stockWidth}" data-stock-length="${c.stockLength}" aria-pressed="${selected}" aria-label="選用 ${esc(c.label)}" class="tank-stock-option"><span class="tank-stock-title"><strong>${esc(c.label)}</strong><span>${selected?'✓ 已選':'選用 →'}</span></span><svg viewBox="0 0 170 55" aria-hidden="true"><rect x="8" y="5" width="${c.stockLength/6096*150}" height="${c.stockWidth/1524*40}" rx="3" fill="#c8ded3" stroke="#62917a"/><path d="M8 12v-7h7" stroke="#bb8136" fill="none"/></svg><small>${fmt(c.stockWidth)} × ${fmt(c.stockLength)} mm</small>${main}${!r.stockComplete&&r.valid?'<span class="tank-stock-warning">'+(r.stockPlan.materialIssues.length?'有毛坯超出板型／數量限制，請看排料待補。':'分件備料資料待補；換板型仍須補資料。')+'</span>':''}${badges.length?'<span class="tank-stock-badges">'+badges.join(' · ')+'</span>':''}</button>${more}</article>`;
}
